<script setup lang="ts">
import { computed, nextTick, ref } from 'vue';
import { useRouter } from 'vue-router';
const router=useRouter(),visible=ref(false),query=ref(''),input=ref<HTMLInputElement|null>(null);
const commands=[{name:'创作概览',path:'/home',hint:'查看任务统计与常用工具'},{name:'创作工作台',path:'/video?tab=ipAgent',hint:'文案、声音、视频、发布'},{name:'数字人形象',path:'/video?tab=videoTemplate',hint:'选择或上传出镜形象'},{name:'声音工作室',path:'/sound',hint:'语音合成与识别'},{name:'素材资源',path:'/video?tab=videoMaterial',hint:'管理视频、图片与音频'},{name:'视频合成',path:'/video?tab=videoGen',hint:'生成数字人视频'},{name:'字幕制作',path:'/video-subtitle',hint:'识别与制作字幕'},{name:'封面设计',path:'/design',hint:'制作视频封面'},{name:'图像创作',path:'/image',hint:'生成与处理图像'},{name:'音频提取',path:'/video?tab=videoAudioExtract',hint:'从视频中提取音频'},{name:'互动直播',path:'/live',hint:'直播与对话'},{name:'实用工具',path:'/tool',hint:'更多创作工具'},{name:'模型服务',path:'/server',hint:'配置本地和云端模型'},{name:'偏好设置',path:'/setting',hint:'Ctrl / ⌘ ,'}];
const results=computed(()=>commands.filter(c=>!['/design','/image','/tool','/live'].includes(c.path)&&(c.name+c.hint).includes(query.value.trim())));
let previousFocus:HTMLElement|null=null;
const show=async()=>{previousFocus=document.activeElement as HTMLElement;query.value='';visible.value=true;await nextTick();input.value?.focus();};
const close=()=>{visible.value=false;previousFocus?.focus();};
const navigate=(path:string)=>{visible.value=false;router.push(path);};
const focusResult=()=>{(document.querySelector('.command-results button') as HTMLButtonElement)?.focus();};
const move=(e:KeyboardEvent)=>{if(!['ArrowDown','ArrowUp'].includes(e.key))return;e.preventDefault();const nodes=Array.from(document.querySelectorAll<HTMLButtonElement>('.command-results button'));const i=nodes.indexOf(document.activeElement as HTMLButtonElement);nodes[(i+(e.key==='ArrowDown'?1:-1)+nodes.length)%nodes.length]?.focus();};
defineExpose({show});
</script>
<template><a-modal v-model:visible="visible" title="前往页面" :esc-to-close="true" :footer="false" :width="560" @cancel="close" @close="close" :unmount-on-close="true"><label for="command-search" class="command-label">搜索页面或功能</label><input id="command-search" ref="input" v-model="query" class="command-search" placeholder="例如：素材、声音、设置" autocomplete="off" @keydown.down.prevent="focusResult" @keydown.enter.prevent="results[0]&&navigate(results[0].path)"/><div class="command-results" @keydown="move"><button v-for="item in results" :key="item.path" type="button" @click="navigate(item.path)"><span>{{item.name}}<small>{{item.hint}}</small></span><span aria-hidden="true">↵</span></button><p v-if="!results.length" role="status">未找到相关页面，请换一个关键词。</p></div><p class="command-help">↑ ↓ 选择 · Enter 打开 · Esc 关闭</p></a-modal></template>
<style scoped>.command-label{display:block;font-size:13px;margin-bottom:8px;color:var(--theme-text-secondary)}.command-search{box-sizing:border-box;width:100%;height:44px;border:1px solid var(--theme-border-strong);border-radius:9px;padding:0 13px;background:var(--theme-panel-bg-muted);color:var(--theme-text-primary);font-size:15px}.command-results{max-height:360px;overflow:auto;margin:12px -8px 0;padding:4px 8px}.command-results button{width:100%;display:flex;justify-content:space-between;align-items:center;text-align:left;padding:12px;border:0;background:transparent;border-radius:8px;color:var(--theme-text-primary);font-size:14px}.command-results button:hover,.command-results button:focus{background:var(--theme-brand-soft)}.command-results small{display:block;font-size:12px;color:var(--theme-text-muted);margin-top:3px}.command-help{font-size:12px;color:var(--theme-text-muted);margin:12px 0 0;border-top:1px solid var(--theme-border);padding-top:12px}</style>
